ALTER TABLE "tickets" ADD COLUMN "is_bulk" boolean DEFAULT false NOT NULL;--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "tickets_is_bulk_idx" ON "tickets" USING btree ("is_bulk");--> statement-breakpoint
UPDATE "tickets" t SET "is_bulk" = true, "status" = 'UNRESOLVED_CLOSED' WHERE t."status" = 'OPEN' AND t."assignee_id" IS NULL AND t."channel" = 'EMAIL' AND NOT EXISTS (SELECT 1 FROM "messages" m WHERE m."ticket_id" = t."id" AND m."direction" = 'OUTBOUND') AND NOT EXISTS (SELECT 1 FROM "notes" n WHERE n."ticket_id" = t."id") AND EXISTS (SELECT 1 FROM "messages" m WHERE m."ticket_id" = t."id" AND m."direction" = 'INBOUND' AND (m."is_auto_reply" = true OR m."body_html" ILIKE '%unsubscribe%'));--> statement-breakpoint
UPDATE "tickets" t SET "is_bulk" = true WHERE t."is_bulk" = false AND t."status" IN ('RESOLVED_CLOSED', 'UNRESOLVED_CLOSED') AND t."assignee_id" IS NULL AND t."channel" = 'EMAIL' AND NOT EXISTS (SELECT 1 FROM "messages" m WHERE m."ticket_id" = t."id" AND m."direction" = 'OUTBOUND') AND NOT EXISTS (SELECT 1 FROM "notes" n WHERE n."ticket_id" = t."id") AND EXISTS (SELECT 1 FROM "messages" m WHERE m."ticket_id" = t."id" AND m."direction" = 'INBOUND' AND (m."is_auto_reply" = true OR m."body_html" ILIKE '%unsubscribe%'));
